/** Loads an active (not removed, not suspended) member or throws `NotFoundError`. */
async function requireActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

/** True while `at` is inside `[startsAt, endsAt)`. */
export function isAbsentAt(absence: MemberAbsence, at: Date): boolean {
  const time = at.getTime();
  return (
    time >= new Date(absence.startsAt).getTime() &&
    time < new Date(absence.endsAt).getTime()
  );
}

/**
 * The stand-in for `userId` at instant `at`: their delegate while they are
 * away, `null` otherwise. Deliberately one hop — delegation is never chained.
 */
export async function findDelegateAt(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await memberRepo.findAbsence(orgId, userId);
  if (!absence || !isAbsentAt(absence, at)) return null;
  return absence.delegateUserId;
}

/**
 * Marks a member away, replacing any absence already stored. Anyone may set
 * their own; setting someone else's takes the permission to change roles.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const member = await requireActiveMember(input.orgId, input.userId);
  if (member.userId !== actor.userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  if (new Date(input.endsAt).getTime() <= new Date(input.startsAt).getTime()) {
    throw new Error("An absence must end after it starts");
  }

  if (input.delegateUserId !== null) {
    if (input.delegateUserId === input.userId) {
      throw new Error("A member cannot be their own delegate");
    }
    await requireActiveMember(input.orgId, input.delegateUserId);
  }

  return memberRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId: input.delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note,
  });
}

export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  if (userId !== actor.userId) {
    const member = requireFound(
      await memberRepo.findMember(orgId, userId),
      "Member",
      userId,
