/** True while `at` is inside `[startsAt, endsAt)`. */
export function isAbsentAt(absence: MemberAbsence, at: Date): boolean {
  const time = at.getTime();
  return (
    time >= new Date(absence.startsAt).getTime() &&
    time < new Date(absence.endsAt).getTime()
