    orgId: t.org.id, userId: t.userIds.member, delegateUserId: t.userIds.admin,
    startsAt: iso(-1000), endsAt: iso(100000), note: null,
  });
  const b = await memberService.setAbsence(t.actors.member, { ...a, note: "hi" });
  expect(b.note).toBe("hi");
  const issue = await issueService.createIssue(t.actors.owner, {
    ...issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }),
  } as never);
  expect(issue.assigneeId).toBe(t.userIds.admin);
  await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: (await memberRepo.findMember(t.org.id, t.userIds.admin))!.id });
  const c = await memberService.getAbsence(t.actors.owner, t.org.id, t.userIds.member);
  expect(c?.delegateUserId).toBeNull();
});
